<script setup>
import { ref, computed, onMounted, onBeforeUnmount } from 'vue';
import { ArrowUpRight, ArrowRight, ArrowLeft, Plus, Search, BookOpen, Bookmark, Check, CheckCircle2, ChevronRight, ChevronDown, X, FileText, ExternalLink, Download, RefreshCw, LoaderCircle, AlertTriangle, MessageSquare, SlidersHorizontal, ListChecks, Sparkles, Link2, CircleHelp, Layers, PanelLeftClose, Send, ShieldCheck } from 'lucide-vue-next';

const catalog=ref({companies:[],years:[2024,2025],examples:[]});
const form=ref({company:'000858.SZ',year:2024,thesis:'五粮液2024年利润增长主要来自主营业务改善，盈利质量同步提升。',focus:''});
const view=ref('new'), phase=ref('input'), plan=ref(null), result=ref(null), evidence=ref([]), metrics=ref([]), history=ref([]);
const busy=ref(false), error=ref(''), progress=ref(''), step=ref(0), selected=ref(null), tab=ref('all'), question=ref(''), chat=ref([]), chatBusy=ref(false), toast=ref(''), showMethod=ref(false), navOpen=ref(false), health=ref(null);
const saved=ref([]), warnings=ref([]); let aborter=null, toastTimer=null, requestVersion=0;
const labels={supported:'证据支持',partial:'有限支持',contradicted:'存在关键反证',insufficient:'证据尚不足'};
const verdictClass=computed(()=>result.value?.analysis.verdict || 'partial');
const companyName=computed(()=>catalog.value.companies.find(c=>c.code===form.value.company)?.name||'');
const currentSaved=computed(()=>saved.value.some(r=>r.id===result.value?.id));
const supports=computed(()=>new Set(result.value?.analysis.supporting.map(r=>r.evidence_id)||[]));
const opposes=computed(()=>new Set(result.value?.analysis.opposing.map(r=>r.evidence_id)||[]));
const visibleEvidence=computed(()=>evidence.value.filter(e=>tab.value==='all'||tab.value==='documents'&&e.kind==='document'||tab.value==='support'&&supports.value.has(e.id)||tab.value==='oppose'&&opposes.value.has(e.id)));
const maxRevenue=computed(()=>Math.max(...history.value.map(x=>x.revenue||0),1));
const fmt=v=>v==null?'—':(v/1e8).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
const pct=v=>v==null?'无法计算':(v>0?'+':'')+v.toFixed(2)+'%';
const date=s=>s?new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'—';
const shortDate=s=>s?new Date(s).toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai'}):'—';
function message(text){toast.value=text;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',3500);}
async function api(path,body,signal){const r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,signal});if(!r.ok){let d;try{d=await r.json()}catch{};throw new Error(typeof d?.detail==='string'?d.detail:`请求未完成（${r.status}），请检查输入后重试。`);}return r;}
onMounted(async()=>{try{saved.value=JSON.parse(localStorage.getItem('thesis-lab-studies')||'[]');if(!Array.isArray(saved.value))saved.value=[];}catch{saved.value=[];}try{const [c,h]=await Promise.all([(await api('catalog')).json(),(await api('health')).json()]);catalog.value=c;health.value=h;}catch(e){error.value='服务连接失败，请确认后端已启动。';}});
onBeforeUnmount(()=>{aborter?.abort();clearTimeout(toastTimer)});
function reset(){requestVersion++;aborter?.abort();busy.value=false;phase.value='input';view.value='new';plan.value=null;result.value=null;evidence.value=[];metrics.value=[];history.value=[];error.value='';chat.value=[];chatBusy.value=false;selected.value=null;warnings.value=[];tab.value='all';navOpen.value=false;}
function example(ex){reset();form.value={company:ex.company,year:ex.year,thesis:ex.thesis,focus:''};}
function stop(){requestVersion++;aborter?.abort();busy.value=false;phase.value=plan.value?'plan':'input';message('已停止等待，已有证据保留。服务端已发出的模型请求可能仍会完成。');}
async function makePlan(){const version=++requestVersion;error.value='';busy.value=true;phase.value='planning';aborter=new AbortController();try{const nextPlan=await(await api('plan',form.value,aborter.signal)).json();if(version!==requestVersion)return;plan.value=nextPlan;phase.value='plan';}catch(e){if(version!==requestVersion)return;if(e.name!=='AbortError')error.value=e.message;phase.value='input';}finally{if(version===requestVersion)busy.value=false;}}
async function run(){const version=++requestVersion;error.value='';result.value=null;chat.value=[];busy.value=true;phase.value='running';step.value=1;progress.value='准备获取财务数据';evidence.value=[];metrics.value=[];history.value=[];warnings.value=[];aborter=new AbortController();try{const r=await api('research',form.value,aborter.signal);const reader=r.body.getReader(),decoder=new TextDecoder();let buf='',completed=false;while(true){const {done,value}=await reader.read();if(version!==requestVersion)return;if(done)break;buf+=decoder.decode(value,{stream:true});const lines=buf.split('\n');buf=lines.pop();for(const line of lines){if(!line.trim())continue;const ev=JSON.parse(line);if(ev.type==='stage'){step.value=ev.step;progress.value=ev.message;}if(ev.type==='evidence'){evidence.value=ev.evidence;metrics.value=ev.metrics;history.value=ev.history;warnings.value=ev.warnings;}if(ev.type==='error')throw new Error(ev.message);if(ev.type==='result'){result.value=ev.result;phase.value='result';step.value=3;completed=true;}}}if(!completed)throw new Error('连接提前结束，未收到完整结论。请重试。');}catch(e){if(version!==requestVersion)return;if(e.name!=='AbortError')error.value=e.message;phase.value='plan';}finally{if(version===requestVersion)busy.value=false;}}
function save(){if(!result.value)return;if(currentSaved.value){message('这份研究已保存');return;}const next=[JSON.parse(JSON.stringify(result.value)),...saved.value].slice(0,20);try{localStorage.setItem('thesis-lab-studies',JSON.stringify(next));saved.value=next;message('已保存到当前浏览器，可在「研究档案」中查看');}catch{message('浏览器存储空间不足，请导出研究文件。');}}
function openStudy(study){reset();result.value=study;form.value={...study.input};evidence.value=study.evidence;metrics.value=study.metrics;history.value=study.history;warnings.value=study.warnings||[];phase.value='result';view.value='new';}
function exportStudy(){if(!result.value)return;const blob=new Blob([JSON.stringify(result.value,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`证见-${form.value.company}-${form.value.year}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message('已导出含证据和来源的研究文件');}
async function followup(text){const studyId=result.value?.id;if(chatBusy.value||!result.value)return;const q=(text||question.value).trim();if(!q)return;question.value='';chat.value.push({role:'user',text:q});chatBusy.value=true;try{const data=await(await api('followup',{research_id:result.value.id,question:q})).json();if(result.value?.id!==studyId)return;chat.value.push({role:'assistant',text:data.answer,ids:data.evidence_ids});}catch(e){if(result.value?.id!==studyId)return;chat.value.push({role:'error',text:e.message});}finally{if(result.value?.id===studyId)chatBusy.value=false;}}
function reasonFor(e){return [...(result.value?.analysis.supporting||[]),...(result.value?.analysis.opposing||[])].filter(r=>r.evidence_id===e.id).map(r=>r.reason).join('；');}
function selectId(id){selected.value=evidence.value.find(e=>e.id===id)||null;}
</script>

<template>
  <div class="app-shell">
    <aside class="sidebar" :class="{open:navOpen}">
      <a class="brand" href="#" @click.prevent="reset"><span class="brand-mark">证</span><span>证见<small>THESIS LAB</small></span></a>
      <button class="new-button" @click="reset"><Plus :size="17"/>新建验证<span>↗</span></button>
      <div class="nav-label">研究空间</div>
      <button class="nav-item" :class="{active:view==='new'}" @click="view='new';navOpen=false"><Layers :size="18"/>命题工作台</button>
      <button class="nav-item" :class="{active:view==='library'}" @click="view='library';navOpen=false"><Bookmark :size="18"/>研究档案<span class="nav-count">{{saved.length}}</span></button>
      <button class="nav-item" @click="showMethod=true;navOpen=false"><BookOpen :size="18"/>验证方法</button>
      <div class="sidebar-note"><div class="tiny-line"></div><p>好的判断，<br/>经得起反证。</p><span>让每一个结论<br/>都能回到证据。</span></div>
      <div class="sidebar-bottom"><span class="status-dot" :class="{offline:!health?.model_configured}"></span><span>{{health?.model_configured?'研究服务已连接':'正在连接研究服务'}}</span><small>v1.0</small></div>
    </aside>

    <main class="main">
      <header class="topbar"><div class="breadcrumbs"><button class="mobile-menu icon-button" aria-label="打开导航" @click="navOpen=!navOpen"><Layers :size="19"/></button><span>研究空间</span><ChevronRight :size="14"/><strong>{{view==='library'?'研究档案':'命题工作台'}}</strong></div><div class="topbar-right"><span class="research-tag">投资研究 · 盈利质量</span><button class="avatar" @click="showMethod=true" aria-label="查看产品说明">研</button></div></header>

      <div v-if="view==='library'" class="content library">
        <div class="eyebrow">YOUR RESEARCH</div><h1>研究档案</h1><p class="subtitle">保存判断，也保留判断背后的依据。</p>
        <div class="notice"><Bookmark :size="17"/>研究仅保存在当前浏览器，不会跨设备同步。重要结果可以导出备份。</div>
        <div v-if="!saved.length" class="empty-state"><BookOpen :size="36"/><h3>还没有保存的研究</h3><p>完成一次验证后，点击“保存研究”即可在这里回看。</p><button class="primary" @click="reset">开始第一份研究<ArrowRight :size="16"/></button></div>
        <button v-for="study in saved" :key="study.id" class="saved-card" @click="openStudy(study)"><div><span class="pill" :class="study.analysis.verdict">{{labels[study.analysis.verdict]}}</span><h3>{{study.input.thesis}}</h3><p>{{shortDate(study.created_at)}} · {{study.evidence.length}} 条可追溯证据</p></div><ArrowUpRight :size="22"/></button>
      </div>

      <div v-else class="content">
        <template v-if="!result">
          <section class="hero"><div><div class="eyebrow"><span></span>EVIDENCE BEFORE CONVICTION</div><h1>先有判断，<br class="mobile-break"/>再让证据说话<span class="title-dot">。</span></h1><p class="subtitle">把一个投资想法，拆成可验证的问题。看清支持、反对，以及尚未知道的部分。</p></div><div class="hero-seal"><span>事实</span><Link2 :size="21"/><span>判断</span><small>有据可循</small></div></section>
          <div class="workflow"><span :class="{current:phase==='input'||phase==='planning'}"><b>01</b>明确命题</span><i></i><span :class="{current:phase==='plan'}"><b>02</b>确认验证路径</span><i></i><span :class="{current:phase==='running'}"><b>03</b>核验证据与结论</span></div>
          <div v-if="error" class="error-box" role="alert"><AlertTriangle :size="19"/><div><strong>这次验证尚未完成</strong><p>{{error}}</p></div><button class="icon-button" aria-label="关闭错误提示" @click="error='' "><X :size="16"/></button></div>
          <section v-if="phase==='input'||phase==='planning'" class="input-card">
            <div class="card-heading"><span class="section-icon"><MessageSquare :size="19"/></span><h2>你想验证什么？</h2><span class="muted small">写下判断，而不只是一个问题</span></div>
            <label class="sr-only" for="thesis">投资命题</label><textarea id="thesis" v-model="form.thesis" maxlength="600" :disabled="busy" placeholder="例如：某公司利润增长主要来自主营业务改善，而非一次性收益。"></textarea>
            <div class="input-bottom"><div class="field-row"><label>研究公司<select v-model="form.company" :disabled="busy"><option v-for="c in catalog.companies" :value="c.code">{{c.name}} · {{c.code}}</option></select></label><label>报告期<select v-model.number="form.year" :disabled="busy"><option v-for="y in catalog.years" :value="y">{{y}} 年报</option></select></label></div><button class="primary" :disabled="busy||form.thesis.trim().length<8||!health" @click="makePlan"><LoaderCircle v-if="busy" class="spin" :size="17"/><Sparkles v-else :size="17"/>{{busy?'正在理解命题':'拆解并澄清命题'}}<ArrowRight v-if="!busy" :size="16"/></button></div>
            <div class="input-footnote"><ShieldCheck :size="14"/><span>使用真实财务数据与公开年报 · 年度研究，无需实时行情</span><span>{{form.thesis.length}} / 600</span></div>
          </section>

          <section v-if="phase==='plan'||phase==='running'" class="plan-card">
            <div class="card-heading"><span class="section-icon"><ListChecks :size="20"/></span><h2>先对齐，我们要验证的判断</h2><span class="badge">{{companyName}} · {{form.year}}</span></div>
            <p class="muted">AI 建议表述如下。你可以直接修订，也可以保留自己的原始命题。</p>
            <div class="refined"><Sparkles :size="17"/><p>{{plan?.refined_thesis}}</p><button v-if="phase==='plan'" type="button" class="secondary adopt-thesis" @click="form.thesis=plan.refined_thesis"><Check :size="15"/>采用此表述</button></div>
            <label class="field-title" for="confirmed-thesis">本次确认命题</label><textarea id="confirmed-thesis" class="compact-textarea" v-model="form.thesis" :disabled="busy" maxlength="600"></textarea>
            <div class="assumptions"><span v-for="a in plan?.assumptions"><Check :size="14"/>{{a}}</span></div>
            <div class="question-grid"><div v-for="q in plan?.questions" :key="q.id"><span>{{q.id}}</span><h3>{{q.title}}</h3><p>{{q.method}}</p></div></div>
            <label class="field-title" for="focus">补充关注点 <span class="muted">（可选）</span></label><input id="focus" v-model="form.focus" :disabled="busy" maxlength="300" placeholder="例如：特别关注非经常性收益与现金流的分歧"/>
            <div class="plan-actions"><button class="secondary" :disabled="busy" @click="phase='input' "><ArrowLeft :size="15"/>返回修改公司 / 年份</button><button v-if="!busy" class="primary" @click="run" :disabled="form.thesis.trim().length<8">确认，开始验证<ArrowRight :size="16"/></button><button v-else class="secondary" @click="stop">停止等待</button></div>
          </section>

          <section v-if="busy&&phase==='running'" class="progress-card" role="status"><LoaderCircle class="spin" :size="22"/><div><strong>{{progress}}</strong><p>仅在收到完整结果并通过引用校验后，才展示验证结论。</p></div><span>{{step}} / 3</span></section>
          <section v-if="phase==='input'||phase==='planning'" class="examples"><div class="section-top"><h2>从一个真实案例开始</h2><span>同一方法，不同的证据走向</span></div><div class="example-grid"><button v-for="(ex,i) in catalog.examples" :key="ex.id" class="example-card" :disabled="busy" @click="example(ex)"><div><span class="example-index">0{{i+1}}</span><ArrowUpRight :size="18"/></div><span class="example-tag">{{ex.tag}}</span><h3>{{ex.title}}</h3><p>{{catalog.companies.find(c=>c.code===ex.company)?.name}} · {{ex.year}} 年度</p></button></div></section>
          <div v-if="!evidence.length" class="principles"><div><Link2 :size="18"/><b>结论可追溯</b><span>回到原始字段和年报页码</span></div><div><SlidersHorizontal :size="18"/><b>主动寻找反证</b><span>不把验证变成自我说服</span></div><div><CircleHelp :size="18"/><b>保留不确定性</b><span>缺失和冲突也属于研究结果</span></div></div>
        </template>

        <template v-if="result">
          <div class="result-top"><button class="text-button" @click="reset"><ArrowLeft :size="16"/>新建验证</button><div><span class="small muted">{{shortDate(result.created_at)}} · {{result.meta.model}}</span><button class="secondary" @click="exportStudy"><Download :size="16"/>导出</button><button class="primary small-button" @click="save"><Check v-if="currentSaved" :size="16"/><Bookmark v-else :size="16"/>{{currentSaved?'已保存':'保存研究'}}</button></div></div>
          <div class="eyebrow">RESEARCH BRIEF · {{form.year}}</div><h1 class="result-title">{{form.thesis}}</h1><div class="result-meta"><span>{{companyName}} · {{form.company}}</span><span>合并年报 · 归母净利润口径</span><span>{{evidence.length}} 条证据</span></div>
          <section class="verdict-card" :class="verdictClass"><div class="verdict-label"><span class="pill" :class="verdictClass">{{labels[result.analysis.verdict]}}</span><span class="small">当前结论 · 随证据修订</span></div><h2>{{result.analysis.headline}}</h2><p>{{result.analysis.summary}}</p><div class="verdict-foot"><ShieldCheck :size="15"/><span>研究判断，不构成投资建议。证据同源不重复计权。</span><span>{{(result.meta.elapsed_ms/1000).toFixed(1)}}s 分析</span></div></section>
          <div class="metric-grid"><div class="metric-card" v-for="m in metrics" :key="m.field"><div>{{m.label}}<span>亿元</span></div><strong>{{fmt(m.value)}}</strong><span class="metric-change" :class="{negative:m.change<0}">{{pct(m.change)}}<small>同比</small></span></div><div class="mini-chart"><div>营收轨迹<span>亿元</span></div><div class="bars"><div v-for="h in history" class="bar-group"><span>{{fmt(h.revenue)}}</span><i :style="{height:(h.revenue||0)/maxRevenue*44+'px'}"></i><small>{{h.year}}</small></div></div></div></div>
          <div class="result-grid"><div class="result-main"><section class="findings-section"><div class="section-top"><h2>四个问题，逐一核验</h2><span>事实与判断分开看</span></div><div class="finding" v-for="f in result.analysis.findings" :key="f.question_id"><span class="finding-index">{{f.question_id}}</span><div><div class="finding-title"><h3>{{result.questions.find(q=>q.id===f.question_id)?.title}}</h3><span class="mini-pill" :class="f.verdict">{{{support:'支持线索',oppose:'反对线索',mixed:'存在分歧',unknown:'尚待验证'}[f.verdict]}}</span></div><p>{{f.answer}}</p><div class="cite-row"><button v-for="id in f.evidence_ids" @click="selectId(id)"><Link2 :size="11"/>{{id}}</button></div></div></div></section>
          <section class="conflict-section" v-if="result.analysis.conflicts.length"><div class="card-heading"><SlidersHorizontal :size="18"/><h2>证据冲突，如何理解？</h2></div><p v-for="c in result.analysis.conflicts">{{c}}</p></section>
          </div><aside class="result-aside"><section class="unknown-card"><div class="card-heading"><CircleHelp :size="19"/><h2>仍然不知道的部分</h2></div><ul><li v-for="item in result.analysis.unknown">{{item}}</li></ul></section><section class="changes-card"><div class="card-heading"><RefreshCw :size="18"/><h2>什么会改变结论？</h2></div><p class="small muted">把不确定性，变成下一步研究。</p><ol><li v-for="item in result.analysis.change_conditions">{{item}}</li></ol></section></aside></div>
        </template>

        <section v-if="evidence.length" class="evidence-section"><div class="section-top"><div><h2>证据桌面 <span class="count">{{evidence.length}}</span></h2><p class="small muted">点击卡片，核对原始字段、计算方式与披露来源。</p></div><span class="badge">真实材料</span></div><div v-if="warnings.length" class="notice warn"><AlertTriangle :size="16"/><span>{{warnings.join(' ')}}</span></div><div class="tabs"><button :class="{active:tab==='all'}" @click="tab='all'">全部证据</button><button v-if="result" :class="{active:tab==='support'}" @click="tab='support'">支持 <span>{{supports.size}}</span></button><button v-if="result" :class="{active:tab==='oppose'}" @click="tab='oppose'">反对 <span>{{opposes.size}}</span></button><button :class="{active:tab==='documents'}" @click="tab='documents'">年报原文</button></div><div class="evidence-grid"><button v-for="e in visibleEvidence" :key="e.id" class="evidence-card" @click="selected=e"><div class="evidence-card-top"><span class="evidence-id">{{e.id}}</span><span>{{e.kind==='document'?'原始披露':e.kind==='calculation'?'派生计算':'财务字段'}}</span><ArrowUpRight :size="16"/></div><h3>{{e.title}}</h3><p>{{e.summary}}</p><div v-if="reasonFor(e)" class="evidence-reason">{{reasonFor(e)}}</div><div class="evidence-card-bottom"><FileText :size="13"/><span>{{e.source}}{{e.page?' · P.'+e.page:''}}</span><i v-if="supports.has(e.id)" class="dot-support"></i><i v-if="opposes.has(e.id)" class="dot-oppose"></i></div></button></div><p v-if="!visibleEvidence.length" class="empty-inline">当前结论没有归入这一类别的证据。没有反证不等于已经证实。</p></section>

        <section v-if="result" class="followup-section"><div class="section-top"><h2>沿着证据，继续追问</h2><MessageSquare :size="20"/></div><div class="suggestions"><button :disabled="chatBusy" @click="followup('哪些证据最可能推翻当前结论？')">哪些证据最可能推翻结论？<Plus :size="13"/></button><button :disabled="chatBusy" @click="followup('现金流与净利润的差异应该如何理解？')">现金流与利润的差异怎么理解？<Plus :size="13"/></button></div><div class="chat-log" aria-live="polite"><div v-for="(m,i) in chat" :key="i" class="chat-message" :class="m.role"><span>{{m.role==='user'?'你':m.role==='error'?'提示':'证见'}}</span><div><p>{{m.text}}</p><div class="cite-row" v-if="m.ids"><button v-for="id in m.ids" @click="selectId(id)"><Link2 :size="11"/>{{id}}</button></div></div></div><div v-if="chatBusy" class="chat-pending"><LoaderCircle class="spin" :size="15"/>正在对照当前研究的证据…</div></div><form class="chat-form" @submit.prevent="followup()"><input aria-label="输入追问" v-model="question" maxlength="500" :disabled="chatBusy" placeholder="追问一个疑点，回答会限定在当前证据范围内"/><button class="primary" aria-label="发送追问" :disabled="chatBusy||question.trim().length<2"><Send :size="17"/></button></form></section>
        <footer><span class="footer-brand">证见 <i>/</i> THESIS LAB</span><span>仅用于投资研究辅助 · 不预测涨跌，不提供买卖建议</span><button class="text-button" @click="showMethod=true">数据与边界<ArrowUpRight :size="13"/></button></footer>
      </div>
    </main>

    <div v-if="selected" class="modal-backdrop" @click.self="selected=null"><section class="evidence-drawer" role="dialog" aria-modal="true" aria-label="证据详情"><div class="drawer-top"><span class="eyebrow">EVIDENCE / {{selected.id}}</span><button class="icon-button" aria-label="关闭证据" @click="selected=null"><X :size="22"/></button></div><h2>{{selected.title}}</h2><span class="badge">{{selected.kind==='document'?'原始披露材料':'可核验的结构化证据'}}</span><p class="drawer-summary">{{selected.summary}}</p><div class="detail-label">来源与口径</div><dl><dt>来源</dt><dd>{{selected.source}}</dd><dt>报告期</dt><dd>{{selected.period}} 年度</dd><template v-if="selected.page"><dt>PDF 页码</dt><dd>第 {{selected.page}} 页</dd><dt>披露日期</dt><dd>{{selected.published_at}}</dd></template><dt>{{selected.kind==='document'?'整理核验日期':'数据获取时间'}}</dt><dd>{{date(selected.fetched_at)}}</dd><dt>获取方式</dt><dd>{{selected.kind==='document'?'预先整理的真实年报片段':selected.cached?'已获取的数据缓存（6小时内）':'本次接口查询'}}</dd></dl><div class="detail-label">{{selected.kind==='document'?'原文与表格摘录':'原始字段与计算方式'}}</div><blockquote v-if="selected.raw.excerpt">{{selected.raw.excerpt}}</blockquote><pre v-else>{{JSON.stringify(selected.raw,null,2)}}</pre><div class="notice"><CircleHelp :size="17"/><span>{{selected.independence_note}}</span></div><p v-if="selected.kind!=='document'" class="small muted">数据接口需鉴权；页面已展示本次返回的原始字段，不会把密钥放入链接。报表日期不直接视为首次披露日期。</p><a class="primary source-link" :href="selected.url" target="_blank" rel="noopener noreferrer">{{selected.kind==='document'?'打开年报原文':'查看接口地址'}}<ExternalLink :size="16"/></a></section></div>
    <div v-if="showMethod" class="modal-backdrop" @click.self="showMethod=false"><section class="method-modal" role="dialog" aria-modal="true" aria-label="验证方法"><div class="drawer-top"><span class="eyebrow">OUR METHOD</span><button class="icon-button" aria-label="关闭说明" @click="showMethod=false"><X :size="22"/></button></div><h2>不替你下判断，<br/>帮你把依据看清楚。</h2><p>证见面向已有投资观点、希望进一步核验的个人研究者。当前专注两家公司的年度盈利质量，使用扶摇真实财务数据及预先核对的公开年报材料。</p><div class="method-item"><b>01 / 拆解与澄清</b><p>AI 辅助明确公司、报告期、利润口径，用户确认后才进行验证。</p></div><div class="method-item"><b>02 / 用证据约束分析</b><p>程序计算财务变化，按公司和报告期定位原文。AI 组织正反证据，服务端校验引用编号；数据缺失不会补成零。</p></div><div class="method-item"><b>03 / 让结论可以被修订</b><p>明确冲突、缺口和改判条件。当前没有全市场检索、实时推送、账户同步或交易功能。材料来自当前可得披露，不是历史时点回测。</p></div><div class="notice"><AlertTriangle :size="18"/><span>AI 仍可能误读证据。涉及重要判断时请回到原始披露；有限支持不等于已经证明因果。</span></div><button class="primary" @click="showMethod=false">了解，回到研究<ArrowRight :size="16"/></button></section></div>
    <div v-if="toast" class="toast" role="status"><CheckCircle2 :size="17"/>{{toast}}</div>
  </div>
</template>
